CREATE TABLE organizations(id UUID PRIMARY KEY, singleton BOOLEAN NOT NULL DEFAULT TRUE UNIQUE CHECK(singleton), name TEXT NOT NULL, acl_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE departments(id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80), parent_id UUID REFERENCES departments(id), UNIQUE(organization_id,name), CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE users(id TEXT PRIMARY KEY REFERENCES auth_users(id), organization_id UUID NOT NULL REFERENCES organizations(id), department_id UUID REFERENCES departments(id), enabled BOOLEAN NOT NULL DEFAULT TRUE, auth_version INTEGER NOT NULL DEFAULT 1, must_change_password BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE permissions(code TEXT PRIMARY KEY);
CREATE TABLE roles(id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, system BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id), role_id UUID NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id UUID NOT NULL REFERENCES roles(id), permission_code TEXT NOT NULL REFERENCES permissions(code), PRIMARY KEY(role_id,permission_code));
CREATE TABLE brand_config(id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(id), organization_id UUID NOT NULL UNIQUE REFERENCES organizations(id), version INTEGER NOT NULL DEFAULT 1, config JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE system_settings(key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE models(id UUID PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, provider_code TEXT NOT NULL CHECK(provider_code='ark'), enabled BOOLEAN NOT NULL DEFAULT TRUE, max_output_tokens INTEGER NOT NULL DEFAULT 2048 CHECK(max_output_tokens BETWEEN 128 AND 8192), price_input NUMERIC, price_output NUMERIC, currency TEXT, price_source TEXT);
CREATE TABLE capabilities(code TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('tool','skill','mcp')), name TEXT NOT NULL, description TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version TEXT NOT NULL);
CREATE TABLE assistants(id UUID PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, model_id UUID NOT NULL REFERENCES models(id), system_prompt TEXT NOT NULL DEFAULT '', tools JSONB NOT NULL DEFAULT '[]', version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE assistant_roles(assistant_id UUID NOT NULL REFERENCES assistants(id), role_id UUID NOT NULL REFERENCES roles(id), PRIMARY KEY(assistant_id,role_id));
CREATE TABLE sessions(id UUID PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), assistant_id UUID NOT NULL REFERENCES assistants(id), title TEXT NOT NULL DEFAULT '新对话', status TEXT NOT NULL DEFAULT 'idle', acl_version BIGINT NOT NULL, knowledge_used BOOLEAN NOT NULL DEFAULT FALSE, snapshot JSONB NOT NULL DEFAULT '{"messages":[],"terminal":"Completed","isRunning":false}', event_cursor BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ);
CREATE INDEX sessions_owner_idx ON sessions(owner_id,updated_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE runs(id UUID PRIMARY KEY, session_id UUID NOT NULL REFERENCES sessions(id), owner_id TEXT NOT NULL REFERENCES users(id), idempotency_key UUID NOT NULL, status TEXT NOT NULL, terminal TEXT, error_code TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), finished_at TIMESTAMPTZ, UNIQUE(owner_id,idempotency_key));
CREATE UNIQUE INDEX one_active_run_per_session ON runs(session_id) WHERE status IN ('queued','running','awaiting_approval');
CREATE TABLE session_events(session_id UUID NOT NULL REFERENCES sessions(id), seq BIGINT NOT NULL, run_id UUID REFERENCES runs(id), type TEXT NOT NULL, data JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(session_id,seq));
CREATE TABLE approvals(id UUID PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), session_id UUID NOT NULL REFERENCES sessions(id), run_id UUID NOT NULL REFERENCES runs(id), runtime_approval_id UUID NOT NULL, tool TEXT NOT NULL, args_hash TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','denied','expired','cancelled')), expires_at TIMESTAMPTZ NOT NULL, decided_at TIMESTAMPTZ);
CREATE TABLE runtimes(user_id TEXT PRIMARY KEY REFERENCES users(id), instance_id UUID NOT NULL UNIQUE, generation INTEGER NOT NULL DEFAULT 1, container_id TEXT, network_name TEXT, state TEXT NOT NULL, runtime_ip INET, gateway_token_hash TEXT, token_expires_at TIMESTAMPTZ, image_digest TEXT NOT NULL, harness_sha TEXT NOT NULL, last_active TIMESTAMPTZ NOT NULL DEFAULT NOW(), error_code TEXT);
CREATE TABLE files(id UUID PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), storage_key TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, mime TEXT NOT NULL, size BIGINT NOT NULL CHECK(size>=0), sha256 TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('upload','generated','brand','knowledge')), scan_status TEXT NOT NULL CHECK(scan_status IN ('pending','clean','rejected')), session_id UUID REFERENCES sessions(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ);
CREATE INDEX files_owner_idx ON files(owner_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE knowledge_bases(id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, acl_version BIGINT NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE documents(id UUID PRIMARY KEY, knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id), name TEXT NOT NULL, file_id UUID NOT NULL REFERENCES files(id), version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL CHECK(status IN ('pending','processing','ready','failed','invalidated')), error_code TEXT, acl_version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ);
CREATE TABLE document_versions(id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES documents(id), version INTEGER NOT NULL, checksum TEXT NOT NULL, parser_version TEXT NOT NULL, text_content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(document_id,version));
CREATE TABLE knowledge_acl(id UUID PRIMARY KEY, knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id), subject_type TEXT NOT NULL CHECK(subject_type IN ('user','department','role','organization')), subject_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('read','manage')), effect TEXT NOT NULL CHECK(effect IN ('allow','deny')), UNIQUE(knowledge_base_id,subject_type,subject_id,action));
CREATE TABLE document_acl(id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES documents(id), subject_type TEXT NOT NULL CHECK(subject_type IN ('user','department','role','organization')), subject_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('read','manage')), effect TEXT NOT NULL CHECK(effect IN ('allow','deny')), UNIQUE(document_id,subject_type,subject_id,action));
CREATE TABLE knowledge_index(id UUID PRIMARY KEY, document_version_id UUID NOT NULL REFERENCES document_versions(id), chunk_index INTEGER NOT NULL, text_content TEXT NOT NULL, search_vector TSVECTOR GENERATED ALWAYS AS(to_tsvector('simple',text_content)) STORED, UNIQUE(document_version_id,chunk_index));
CREATE INDEX knowledge_search_idx ON knowledge_index USING GIN(search_vector);
CREATE TABLE index_jobs(id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES documents(id), status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until TIMESTAMPTZ, error_code TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE assistant_knowledge(assistant_id UUID NOT NULL REFERENCES assistants(id), knowledge_base_id UUID NOT NULL REFERENCES knowledge_bases(id), PRIMARY KEY(assistant_id,knowledge_base_id));
CREATE TABLE audit_heads(id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(id), seq BIGINT NOT NULL DEFAULT 0, hash TEXT NOT NULL);
CREATE TABLE audit_events(seq BIGINT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, resource TEXT, result TEXT NOT NULL, request_id UUID NOT NULL, metadata JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, prev_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE usage_events(id UUID PRIMARY KEY, request_id UUID NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id), department_id UUID, session_id UUID REFERENCES sessions(id), model_code TEXT NOT NULL, input_tokens BIGINT NOT NULL DEFAULT 0, output_tokens BIGINT NOT NULL DEFAULT 0, latency_ms INTEGER NOT NULL, result TEXT NOT NULL, error_code TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX usage_user_time_idx ON usage_events(user_id,created_at);
CREATE TABLE quotas(user_id TEXT PRIMARY KEY REFERENCES users(id), daily_requests INTEGER NOT NULL DEFAULT 200 CHECK(daily_requests>=0), daily_tokens BIGINT NOT NULL DEFAULT 1000000 CHECK(daily_tokens>=0));
CREATE TABLE quota_reservations(id UUID PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), day DATE NOT NULL, reserved_tokens BIGINT NOT NULL CHECK(reserved_tokens>=0), actual_tokens BIGINT, status TEXT NOT NULL CHECK(status IN ('reserved','used','released')), expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX quota_day_idx ON quota_reservations(user_id,day,status);
CREATE TABLE bridge_devices(id UUID PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, public_key TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, revoked_at TIMESTAMPTZ);
CREATE TABLE bridge_grants(id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES bridge_devices(id), display_name TEXT NOT NULL, permission TEXT NOT NULL CHECK(permission IN ('read','write')), revoked_at TIMESTAMPTZ);
CREATE TABLE bridge_operations(id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES bridge_devices(id), grant_id UUID NOT NULL REFERENCES bridge_grants(id), nonce TEXT NOT NULL UNIQUE, action TEXT NOT NULL, status TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
